package main

import (
	"encoding/json"
	"fmt"
	"io"
	"net"
	"sync"
	"time"

	"github.com/jepsen-io/maelstrom/demo/go"
)

const tcpTimeout = 2 * time.Second

// Node is our broadcast node implementation
type Node struct {
	node     maestrom.Node
	myID      string
	values    map[int]int          // msg_id -> value
	messages  []int                // all unique values we have seen
	tcpAddr  net.TCPListener
	peers     map[string]*net.TCPConn // conn -> peer ID
}

func (n *Node) run() error {
	n.node = maestrom.NewNode()

	var initErr error
	initErr, _ = n.node.Init()
	if initErr != nil {
		fmt.Fprintf(n.node.Stderr(), "Init error: %v\n", initErr)
		return initErr
	}

	var myID string
	var peers map[string]string

	err := handleAll(&Request{Type: "init", Body: struct{}{}})
	if err != nil {
		fmt.Fprintf(n.node.Stderr(), "Handle init error: %v\n", err)
		return err
	}

	// Extract myID and peers from init response
	// In real maelstrom, the init handles itself

	tcpAddr := net.ResolveTCPAddr("tcp", "0.0.0.0:0")
	listener, err := net.ListenTCP(tcpAddr)
	if err != nil {
		fmt.Fprintf(n.node.Stderr(), "Listen error: %v\n", err)
		return err
	}
	n.tcpAddr = listener

	// We'll listen for connections and handle peers manually
	go n.handleIncomingConnections()

	err = n.node.Run()
	if err != nil {
		fmt.Fprintf(n.node.Stderr(), "Run error: %v\n", err)
		return err
	}

	return listener.Close()
}

func (n *Node) handleAll(msg any) error {
	var req Request
	data, _ := json.Marshal(msg)
	json.Unmarshal(data, &req)

	switch req.Type {
	case "init":
		err := n.handleInit(&req)
		if err != nil {
			return err
		}
	case "topology":
		err := n.handleTopology(&req)
		if err != nil {
			return err
		}
	case "broadcast":
		err := n.handleBroadcast(&req)
		if err != nil {
			return err
		}
	case "read":
		err := n.handleRead(&req)
		if err != nil {
			return err
		}
	default:
		fmt.Fprintf(n.node.Stderr(), "Unknown message type: %v\n", req.Type)
	}

	return n.node.Reply()
}

func (n *Node) handleInit(req *Request) error {
	var nodeInfo map[string]any
	json.Unmarshal(*req.Body, &nodeInfo)

	myID := nodeInfo["me"].(string)
	peers = make(map[string]string)
	for k, v := range nodeInfo["nodes"].(map[string]any) {
		peers[k] = v.(string)
	}

	n.myID = myID

	// Create a TCP connection to all peers
	for peerID := range peers {
		conn, err := n.connectPeer(peerID)
		if err != nil {
			fmt.Fprintf(n.node.Stderr(), "Connect error: %v\n", err)
			continue
		}
		n.peers[peerID] = conn
	}

	return n.node.Reply(&maestrom.Response{Status: "ok"})
}

func (n *Node) connectPeer(peerID string) (*net.TCPConn, error) {
	addr := fmt.Sprintf("tcp://%s:%d", peers[peerID], tcpPort(0))
	conn, err := net.DialTCP("tcp", nil, addr)
	if err != nil {
		fmt.Fprintf(n.node.Stderr(), "Dial error: %v\n", err)
		return nil, err
	}

	conn.SetDeadline(time.Now().Add(tcpTimeout))
	return conn, nil
}

func (n *Node) handleTopology(req *Request) error {
	topology := req.Body.(map[string][]string)
	n.peers = make(map[string]*net.TCPConn)

	for peerID, connectedPeers := range topology {
		if _, ok := peers[peerID]; !ok {
			continue
		}

		conn, err := n.connectPeer(peerID)
		if err != nil {
			fmt.Fprintf(n.node.Stderr(), "Connect error: %v\n", err)
			continue
		}

		n.peers[peerID] = conn

		// Send all known values to each peer
		for _, val := range n.messages {
			msg := &TopologyMsg{
				Type:  "value_broadcast",
				Value: val,
			}

			jsonData, _ := json.Marshal(msg)
			conn.Write(jsonData)
		}
	}

	return n.node.Reply(&maestrom.Response{Status: "ok"})
}

func (n *Node) handleBroadcast(req *Request) error {
	broadcastReq := req.Body.(map[string]any)
	msgID := broadcastReq["msg_id"].(int)
	value := broadcastReq["value"].(int)

	// Store the value locally
	n.values[msgID] = value
	n.messages = append(n.messages, value)

	return n.node.Reply(&maestrom.Response{Status: "ok"})
}

func (n *Node) handleRead(req *Request) error {
	result := &maestrom.Response{
		Status: "ok",
		Data: map[string]any{"messages": n.messages},
	}

	return n.node.Reply(result)
}

// Handle incoming connections from peers
func (n *Node) handleIncomingConnections() {
	for {
		conn, err := n.tcpAddr.AcceptTCP()
		if err != nil {
			continue
		}

		peerID := ""
		conn.SetDeadline(time.Now().Add(tcpTimeout))

		go n.handlePeerConnection(conn, peerID)
	}
}

func (n *Node) handlePeerConnection(conn net.Conn, peerID string) {
	buf := make([]byte, 1024)

	for {
		n.Read(conn, buf, peerID)
		if err != nil {
			break
		}
	}

	conn.Close()
}

func (n *Node) Read(conn net.Conn, buf []byte, peerID string) error {
	conn.SetReadDeadline(time.Now().Add(tcpTimeout))
	n, err := conn.Read(buf)
	if err != nil {
		return err
	}

	var msg JSONMessage
	err = json.Unmarshal(buf[:n], &msg)
	if err != nil {
		fmt.Fprintf(n.node.Stderr(), "JSON parse error: %v\n", err)
		return err
	}

	switch msg.Type {
	case "value_broadcast":
		value := int(msg.Value)

		// Send this value to all other peers that we haven't sent it to yet
		n.sendToPeers(conn, peerID, value)

	case "error":
	default:
	}

	return nil
}

func (n *Node) sendToPeers(srcConn net.Conn, peerID string, value int) {
	msg := &JSONMessage{
		Type:  "value_broadcast",
		Value: uint32(value),
	}

	jsonData, _ := json.Marshal(msg)
	srcConn.Write(jsonData)
}

