package main

import (
	"encoding/json"
	"fmt"
	"net"
	"os"

	"github.com/jepsen-io/maelstrom/demo/go"
)

const tcpPort = 50000

// BroadcastValue represents a value that was broadcast to a node
type BroadcastValue struct {
	MsgID int `json:"msg_id"`
	Value int `json:"value"`
	Node  string `json:"node_id"`
}

func main() {
	node, err := maestrom.NewNode()
	if err != nil {
		fmt.Fprintf(node.Stderr(), "Failed to create node: %v\n", err)
		return
	}

	// Track broadcast values by msg_id
	values := make(map[int]int)
	messages := []int{} // Track all unique values

	var myID string
	var peers map[string]string

	// Handle init message first
	initErr := node.Init()
	if initErr != nil {
		fmt.Fprintf(node.Stderr(), "Init error: %v\n", initErr)
		return
	}

	myID = node.ID()
	nodeIDs := node.NodeIDs()
	peers = make(map[string]string)
	for _, id := range nodeIDs {
		if id != myID {
			peers[id] = id
		}
	}

	fmt.Fprintf(node.Stderr(), "My ID: %s, Peers: %v\n", myID, peers)

	// Start the event loop - handle messages from stdin
	node.Run()

	// Reply to any pending requests
	if err := node.Reply(); err != nil {
		fmt.Fprintf(node.Stderr(), "Reply error: %v\n", err)
	}
}

// Handle a broadcast request - store the value and forward to peers
func handleBroadcast(msg maestrom.Message) error {
	body := make(map[string]any)
	if err := json.Unmarshal(msg.Body, &body); err != nil {
		return fmt.Errorf("parse body: %w", err)
	}

	msgID := int(body["msg_id"].(float64))
	value := int(body["value"].(float64))
	nodeID := body["node_id"].(string)

	fmt.Fprintf(msg.Stderr(), "Broadcast msg_id=%d value=%d node_id=%s (my_id=%s)\n", 
		msgID, value, nodeID, myID)

	// Store locally
	values[msgID] = value
	messages = append(messages, value)

	// For simplicity, forward to all peers
	for peerID := range peers {
		if err := sendValueToPeer(peerID, msgID, value); err != nil {
			fmt.Fprintf(msg.Stderr(), "Failed to send to %s: %v\n", peerID, err)
			continue
		}
	}

	return nil
}

// Send a value broadcast message to a peer via TCP connection
func sendValueToPeer(peerID string, msgID int, value int) error {
	connStr := fmt.Sprintf("tcp://%s:%d", peerID, tcpPort)

	// First check if we have an existing connection
	if conn, ok := connections[peerID]; ok {
		jsonData, err := json.Marshal(BroadcastValue{MsgID: msgID, Value: value, Node: myID})
		if err == nil {
			conn.Write(jsonData)
			fmt.Fprintf(os.Stderr, "Sent to %s\n", peerID)
		}
		return nil
	}

	// Create TCP connection
	conn, err := net.Dial("tcp", connStr)
	if err != nil {
		fmt.Fprintf(msg.Stderr(), "Dial error: %v\n", err)
		return err
	}

	defer conn.Close()

	jsonData, _ := json.Marshal(BroadcastValue{MsgID: msgID, Value: value, Node: myID})
	conn.Write(jsonData)
	fmt.Fprintf(os.Stderr, "Connected and sent to %s\n", peerID)

	return nil
}

// Handle a topology request - establish connections with all peers
func handleTopology(msg maestrom.Message) error {
	body := make(map[string]any)
	if err := json.Unmarshal(msg.Body, &body); err != nil {
		return fmt.Errorf("parse body: %w", err)
	}

	topology := body["topology"].(map[string][]string)

	fmt.Fprintf(msg.Stderr(), "Topology received, my_id=%s topology=%v\n", 
		myID, topology)

	// Start listening for incoming connections
	if listener, err := net.Listen("tcp", fmt.Sprintf("%d", tcpPort)); err == nil {
		go handleIncoming(listener)
	} else {
		fmt.Fprintf(msg.Stderr(), "Failed to start TCP listener: %v\n", err)
	}

	return nil
}

// Handle incoming connections from peers
func handleIncoming(listener *net.TCPListener) {
	for {
		conn, err := listener.AcceptTCP()
		if err != nil {
			continue
		}

		go func(c net.Conn) {
			buf := make([]byte, 1024)
			n, err := c.Read(buf)
			if err == nil && n > 0 {
				var bv BroadcastValue
				json.Unmarshal(buf[:n], &bv)

				// Store the value on this peer
				values[bv.MsgID] = bv.Value
				messages = append(messages, bv.Value)

				fmt.Fprintf(os.Stderr, "Received broadcast from %s: msg_id=%d value=%d\n", 
					bv.Node, bv.MsgID, bv.Value)

				// Forward to all other peers (except sender)
				for peerID := range connections {
					if peerID != bv.Node && peerID != myID {
						sendValueToPeer(peerID, bv.MsgID, bv.Value)
					}
				}
			}
			c.Close()
		}(conn)
	}
}

// Handle a read request - return all known values
func handleRead(msg maestrom.Message) error {
	result := make(map[string]any)

	// Return sorted messages (unique values)
	fmt.Fprintf(msg.Stderr(), "read: returning %d values\n", len(messages))

	return nil
}

